from __future__ import annotations


def nearest_rung_index(xs: list[float], a: float) -> int:
    v0 = 0
    v1 = .0
    for i in range(0, len(xs)):
        v2 = xs[i]
        v3 = float(abs(((v2) - (a))))
        if ((v3) < (v1)):
            v1 = v3
            v0 = i
    return v0
